      boxshadow: 0 12px 32px rgba(0, 153, 255, 0.4), 0 0 20px rgba(0, 212, 255, 0.2);
      transform: translateY(50px) scale(0.9);
      transition: all 0.5s cubicbezier(0.25, 0.46, 0.45, 0.94);
    }

    .calendarmodal.show .calendarcontainer {
      transform: translateY(0) scale(1);
    }

    .calendarheader {
      display: flex;
      justifycontent: spacebetween;
      alignitems: center;
      marginbottom: 1.5rem;
      color: white;
    }

    .calendarheader h2 {
      fontsize: 1.4rem;
      fontweight: 600;
      margin: 0;
    }

    .backbtn {
      background: rgba(255, 255, 255, 0.2);
      border: none;
      color: white;
      padding: 6px 12px;
      borderradius: 8px;
      cursor: pointer;
      fontsize: 0.8rem;
      transition: all 0.3s ease;
    }

    .backbtn:hover {
      background: rgba(255, 255, 255, 0.3);
      transform: translateX(2px);
    }

    / Date Selection Phase /
    .dateselection {
      textalign: center;
    }

    .alldatebuttons {
      display: flex;
      gap: 0.5rem;
      alignitems: stretch;
    }

    .quickdatebuttons {
      display: flex;
      gap: 0.5rem;
      flex: 2;
    }

    .quickdatebtn {
      flex: 1;
      background: var(primarygradient);
      border: 1px solid rgba(0, 212, 255, 0.3);
      borderradius: 8px;
      padding: 0.5rem 0.4rem;
      color: white;
      cursor: pointer;
      transition: all 0.3s ease;
      textalign: center;
      minheight: 60px;
      display: flex;
      flexdirection: column;
      justifycontent: center;
    }

    .quickdatebtn:hover {
      background: var(hovergradient);
      bordercolor: 00d4ff;
      transform: translateY(2px);
      boxshadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .quickdatebtn.selected {
      background: var(selectedgradient);
      bordercolor: 00d4ff;
      boxshadow: 0 6px 16px rgba(0, 122, 255, 0.4);
    }

    .datelabel {
      fontweight: 600;
      fontsize: 0.9rem;
      marginbottom: 0.25rem;
    }

    .datevalue {
      fontsize: 0.8rem;
      opacity: 0.8;
    }

    .calendaropenbtn {
      background: var(primarygradient);
      border: 1px solid rgba(0, 212, 255, 0.3);
      color: white;
      padding: 0.5rem 0.75rem;
      borderradius: 8px;
      fontweight: 500;
      cursor: pointer;
      transition: all 0.3s ease;
      fontsize: 0.8rem;
      flex: 1;
      minheight: 60px;
      display: flex;
      alignitems: center;
      justifycontent: center;
    }

    .calendaropenbtn:hover {
      background: var(hovergradient);
      bordercolor: 00d4ff;
      transform: translateY(2px);
      boxshadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    / Calendar View /
    .calendarnav {
      display: flex;
      justifycontent: spacebetween;
      alignitems: center;
      marginbottom: 1rem;
    }

    .calendarnav button {
      background: rgba(255, 255, 255, 0.2);
      border: none;
      color: white;
      width: 32px;
      height: 32px;
      borderradius: 8px;
      cursor: pointer;
      fontsize: 1.2rem;
      transition: background 0.3s ease;
    }

    .calendarnav button:hover {
      background: rgba(255, 255, 255, 0.3);
    }

    .calendarnav h3 {
      color: white;
      margin: 0;
      fontsize: 1.2rem;
    }

    .calendargrid {
      marginbottom: 1.5rem;
    }

    .weekdays {
      display: grid;
      gridtemplatecolumns: repeat(7, 1fr);
      gap: 0.5rem;
      marginbottom: 1rem;
      textalign: center;
      color: rgba(255, 255, 255, 0.7);
      fontweight: 600;
    }

    .datesgrid {
      display: grid;
      gridtemplatecolumns: repeat(7, 1fr);
      gap: 0.5rem;
    }

    .datecell {
      aspectratio: 1;
      display: flex;
      alignitems: center;
      justifycontent: center;
      background: lineargradient(135deg, rgba(0, 153, 255, 0.15) 0%, rgba(0, 78, 146, 0.1) 100%);
      border: 1px solid rgba(0, 212, 255, 0.2);
      borderradius: 8px;
      color: white;
      cursor: pointer;
      transition: all 0.3s ease;
      fontweight: 500;
    }

    .datecell:hover {
      background: lineargradient(135deg, rgba(0, 122, 255, 0.3) 0%, rgba(0, 153, 255, 0.2) 100%);
      bordercolor: 00d4ff;
      transform: scale(1.05);
      boxshadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .datecell.selected {
      background: lineargradient(135deg, 0099ff 0%, 007aff 100%);
      bordercolor: 00d4ff;
      boxshadow: 0 6px 16px rgba(0, 122, 255, 0.4);
    }

    .datecell.othermonth {
      color: rgba(255, 255, 255, 0.3);
    }

    .backtoquick {
      background: lineargradient(135deg, rgba(0, 153, 255, 0.15) 0%, rgba(0, 78, 146, 0.1) 100%);
      border: 1px solid rgba(0, 212, 255, 0.3);
      color: white;
      padding: 10px 20px;
      borderradius: 12px;
      cursor: pointer;
      transition: all 0.3s ease;
      fontsize: 0.9rem;
      width: 100%;
    }

    .backtoquick:hover {
      background: lineargradient(135deg, rgba(0, 153, 255, 0.25) 0%, rgba(0, 122, 255, 0.15) 100%);
      bordercolor: 00d4ff;
      boxshadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    / Weekly View Styles /
    .weeklydatesgrid {
      display: grid;
      gridtemplatecolumns: repeat(7, 1fr);
      gap: 0.5rem;
      marginbottom: 1.5rem;
    }

    .weeklydaycard {
      background: lineargradient(135deg, rgba(26, 26, 58, 0.9) 0%, rgba(13, 20, 33, 0.85) 50%, rgba(30, 58, 95, 0.8) 100%);
      border: 1px solid rgba(0, 212, 255, 0.2);
      borderradius: 8px;
      padding: 0.75rem;
      cursor: pointer;
      transition: all 0.3s ease;
      textalign: center;
      minheight: 100px;
      display: flex;
      flexdirection: column;
      justifycontent: spacebetween;
    }

    .weeklydaycard:hover {
      background: lineargradient(135deg, rgba(0, 122, 255, 0.3) 0%, rgba(0, 78, 146, 0.25) 100%);
      bordercolor: 00d4ff;
      transform: translateY(2px);
      boxshadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .weeklydaycard.selected {
      background: lineargradient(135deg, 0099ff 0%, 007aff 100%);
      bordercolor: 00d4ff;
      boxshadow: 0 6px 16px rgba(0, 122, 255, 0.4);
    }

    .weeklydaycard.disabled {
      opacity: 0.3;
      cursor: notallowed;
      pointerevents: none;
    }

    .weeklydayheader {
      color: white;
      fontweight: 600;
      marginbottom: 0.5rem;
    }

    .weeklydaydate {
      fontsize: 1.2rem;
      fontweight: 700;
      color: white;
      marginbottom: 0.5rem;
    }

    .weeklydayslots {
      display: flex;
      flexdirection: column;
      gap: 0.25rem;
    }

    .weeklytimeslot {
      background: rgba(255, 255, 255, 0.2);
      border: none;
      color: white;
      padding: 0.25rem 0.5rem;
      borderradius: 6px;
      cursor: pointer;
      fontsize: 0.8rem;
      transition: all 0.2s ease;
    }

    .weeklytimeslot:hover {
      background: rgba(255, 255, 255, 0.3);
    }

    .weeklytimeslot.selected {
      background: 34c759;
      fontweight: 600;
    }

    / Time Selection Phase /
    .selecteddateinfo {
      textalign: center;
      marginbottom: 1.5rem;
      color: white;
      fontsize: 1.1rem;
      fontweight: 600;
    }

    .timeslotsgrid {
      display: grid;
      gridtemplatecolumns: repeat(2, 1fr);
      gap: 1rem;
      marginbottom: 1.5rem;
    }

    .timeslot {
      background: lineargradient(135deg, rgba(26, 26, 58, 0.9) 0%, rgba(13, 20, 33, 0.85) 50%, rgba(30, 58, 95, 0.8) 100%);
      border: 1px solid rgba(0, 212, 255, 0.3);
      color: white;
      padding: 0.75rem;
      borderradius: 12px;
      cursor: pointer;
      transition: all 0.3s ease;
      fontweight: 500;
      fontsize: 1rem;
    }

    .timeslot:hover {
      background: lineargradient(135deg, rgba(0, 122, 255, 0.3) 0%, rgba(0, 153, 255, 0.2) 100%);
      bordercolor: 00d4ff;
      transform: translateY(2px);
      boxshadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    .timeslot.selected {
      background: lineargradient(135deg, 0099ff 0%, 007aff 100%);
      bordercolor: 00d4ff;
      boxshadow: 0 6px 16px rgba(0, 122, 255, 0.4);
    }

    .backtodates {
      background: lineargradient(135deg, rgba(0, 153, 255, 0.15) 0%, rgba(0, 78, 146, 0.1) 100%);
      border: 1px solid rgba(0, 212, 255, 0.3);
      color: white;
      padding: 10px 20px;
      borderradius: 12px;
      cursor: pointer;
      transition: all 0.3s ease;
      fontsize: 0.9rem;
      width: 100%;
    }

    .backtodates:hover {
      background: lineargradient(135deg, rgba(0, 153, 255, 0.25) 0%, rgba(0, 122, 255, 0.15) 100%);
      bordercolor: 00d4ff;
      boxshadow: 0 4px 12px rgba(0, 122, 255, 0.3);
    }

    / Animation classes /
    .slideoutleft {
      animation: slideOutLeft 2s cubicbezier(0.25, 0.46, 0.45, 0.94) forwards;
    }

    .slideoutright {
      animation: slideOutRight 2s cubicbezier(0.25, 0.46, 0.45, 0.94) forwards;
    }

    .slideoutup {
      animation: slideOutUp 2s cubicbezier(0.25, 0.46, 0.45, 0.94) forwards;
    }

    .slideoutdown {
      animation: slideOutDown 2s cubicbezier(0.25, 0.46, 0.45, 0.94) forwards;
    }

    @keyframes slideOutLeft {
      to {
        transform: translateX(100vw);
        opacity: 0;
      }
    }

    @keyframes slideOutRight {
      to {
        transform: translateX(100vw);
        opacity: 0;
      }
    }

    @keyframes slideOutUp {
      to {
        transform: translateY(100vh);
        opacity: 0;
      }
    }

    @keyframes slideOutDown {
      to {
        transform: translateY(100vh);
        opacity: 0;
      }
    }

    .cardscontainer {
      position: fixed;
      bottom: 50px;
      left: 0;
      width: 100%;
      padding: 1rem 0 3rem;
      background: lineargradient(135deg, rgba(0, 78, 146, 0.9) 0%, rgba(0, 4, 40, 0.85) 50%, rgba(10, 10, 35, 0.8) 100%);
      backdropfilter: saturate(180%) blur(20px);
      webkitbackdropfilter: saturate(180%) blur(20px);
      boxshadow: 0 2px 20px rgba(0, 153, 255, 0.3);
      bordertop: 1px solid rgba(0, 212, 255, 0.2);
      overflowx: auto;
      scrollsnaptype: x mandatory;
      webkitoverflowscrolling: touch;
      scrollbarwidth: none;
      msoverflowstyle: none;
      display: flex;
      alignitems: center;
      scrollbehavior: smooth;
      overscrollbehaviorx: contain;
    }

    .cardscontainer::webkitscrollbar {
      display: none;
    }

    .cards {
      display: flex;
      gap: 1rem;
      paddingleft: 1rem;
    }

    .card {
      flex: 0 0 60vw;
      maxwidth: 240px;
      background: lineargradient(135deg, 1a1a3a 0%, 0d1421 50%, 1e3a5f 100%);
      border: 1px solid rgba(0, 212, 255, 0.2);
      borderradius: 19px;
      boxshadow: 0 8px 24px rgba(0, 153, 255, 0.2), 0 0 0 1px rgba(0, 212, 255, 0.1);
      scrollsnapalign: center;
      position: relative;
      overflow: hidden;
      display: flex;
      flexdirection: column;
      cursor: grab;
      transition: boxshadow 0.3s cubicbezier(0.25, 0.46, 0.45, 0.94), 
                  transform 0.3s cubicbezier(0.25, 0.46, 0.45, 0.94),
                  filter 0.3s ease;
      willchange: transform;
    }

    .card:active {
      cursor: grabbing;
    }

    .card:hover {
      boxshadow: 0 12px 32px rgba(0, 153, 255, 0.4), 0 0 20px rgba(0, 212, 255, 0.3);
      transform: translateY(4px);
      bordercolor: rgba(0, 212, 255, 0.4);
    }

    .cardbadge {
      position: absolute;
      top: 16px;
      right: 16px;
      background: 007aff;
      color: white;
      fontweight: 600;
      fontsize: 0.75rem;
      padding: 6px 14px;
      borderradius: 12px;
      userselect: none;
      boxshadow: 0 2px 6px rgba(0, 122, 255, 0.4);
      zindex: 2;
    }

    .cardbadge.popular {
      background: 34c759;
      boxshadow: 0 2px 6px rgba(52, 199, 89, 0.4);
    }

    .card video {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 144px;
      objectfit: cover;
      bordertopleftradius: 19px;
      bordertoprightradius: 19px;
      backgroundcolor: rgba(0, 0, 0, 0.2);
      zindex: 0;
      userselect: none;
      filter: brightness(0.9);
    }

    .cardcontent {
      position: relative;
      zindex: 1;
      padding: 1.2rem 1rem 1.6rem;
      margintop: 144px;
      display: flex;
      flexdirection: column;
      justifycontent: spacebetween;
    }

    .card h3 {
      fontsize: 1.3rem;
      fontweight: 700;
      color: fff;
      marginbottom: 0.3rem;
    }

    .card p {
      fontsize: 0.95rem;
      color: 8e8e93;
      marginbottom: 1rem;
    }

    .cardprice {
      fontsize: 1.5rem;
      fontweight: 700;
      color: 007aff;
      marginbottom: 1.5rem;
    }

    .card button {
      background: 007aff;
      border: none;
      padding: 0.5rem 0;
      borderradius: 12px;
      color: white;
      fontweight: 500;
      fontsize: 0.9rem;
      boxshadow: 0 3px 6px rgba(0, 122, 255, 0.3);
      cursor: pointer;
      transition: backgroundcolor 0.3s ease, transform 0.2s ease;
    }

    .card button:hover {
      background: 005ecb;
      transform: translateY(2px);
    }

    .card button:active {
      background: 004bb5;
      transform: translateY(0);
    }

    .modal {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.85);
      backdropfilter: blur(20px);
      webkitbackdropfilter: blur(20px);
      justifycontent: center;
      alignitems: center;
      zindex: 1000;
      padding: 1rem;
    }

    .modalcontent {
      background: 1c1c1e;
      borderradius: 24px;
      maxwidth: 400px;
      width: 100%;
      padding: 2rem;
      color: fff;
      boxshadow: 0 12px 36px rgba(0, 0, 0, 0.3);
      position: relative;
      animation: modalFadeIn 0.3s ease forwards;
    }

    @keyframes modalFadeIn {
      from {
        opacity: 0;
        transform: translateY(20px);
      }

      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .close {
      position: absolute;
      top: 16px;
      right: 16px;
      fontsize: 1.5rem;
      color: 8e8e93;
      cursor: pointer;
      userselect: none;
      transition: color 0.3s ease;
      zindex: 2;
    }

    .close:hover {
      color: fff;
    }

    modaltitle {
      fontweight: 700;
      fontsize: 1.4rem;
      marginbottom: 1rem;
      textalign: center;
    }

    .modaldivider {
      height: 1px;
      background: 2c2c2e;
      margin: 1rem 0 1.5rem;
    }

    .paymentdetails {
      fontsize: 1rem;
      color: fff;
    }

    .paymentrow {
      display: flex;
      justifycontent: spacebetween;
      alignitems: center;
      marginbottom: 1rem;
      fontweight: 500;
      flexwrap: nowrap;
    }

text
    .payment-row.total {
      font-weight: 700;
      font-size: 1.2rem;
      color: #007aff;
      margin-top: 1.5rem;
    }

    .copy-group {
      display: flex;
      gap: 0.5rem;
      align-items: center;
      flex-shrink: 0;
      min-width: 0;
    }

    .copy-text {
      user-select: text;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      min-width: 0;
      flex-shrink: 1;
    }

    .payment-row button {
      background: #2c2c2e;
      border: none;
      border-radius: 8px;
      padding: 0.25rem 0.75rem;
      font-size: 0.85rem;
      cursor: pointer;
      color: #007aff;
      transition: background-color 0.3s ease;
      flex-shrink: 0;
      white-space: nowrap;
    }

    .payment-row button:hover {
      background: #3a3a3c;
    }

    .modal-footer {
      margin-top: 2rem;
      text-align: center;
    }

    .close-btn {
      background: #007aff;
      border: none;
      color: white;
      padding: 0.5rem 1.5rem;
      border-radius: 12px;
      font-weight: 600;
      cursor: pointer;
      font-size: 0.9rem;
      box-shadow: 0 3px 6px rgba(0, 122, 255, 0.3);
      transition: background-color 0.3s ease, transform 0.2s ease;
    }

    .close-btn:hover {
      background: #005ecb;
      transform: translateY(-2px);
    }

    .close-btn:active {
      background: #004bb5;
      transform: translateY(0);
    }

    .toast {
      position: fixed;
      bottom: 20px;
      left: 50%;
      transform: translateX(-50%) translateY(100px);
      background-color: #007aff;
      color: white;
      padding: 12px 24px;
      border-radius: 50px;
      z-index: 2000;
      box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
      opacity: 0;
      transition: transform 0.3s, opacity 0.3s;
      font-weight: 600;
      font-size: 1rem;
    }

    .toast.show {
      transform: translateX(-50%) translateY(0);
      opacity: 1;
    }

    .payment-toast {
      background: linear-gradient(135deg, #34c759 0%, #30d158 100%);
      min-width: 280px;
      padding: 1rem 1.5rem;
    }

    /* Mobile optimizations */
    @media (max-width: 480px) {
      body {
        padding-top: 140px;
        padding-bottom: 40vh;
      }

      .header-container {
        padding: 0.75rem 0.75rem 1.5rem;
      }

      h1 {
        font-size: 1.5rem;
      }

      .subtitle {
        font-size: 1rem;
      }

      .appointment-btn {
        padding: 10px 18px;
        font-size: 0.85rem;
      }

      .card {
        flex: 0 0 75vw;
        max-width: 280px;
      }

      .cards-container {
        bottom: -40px;
        padding: 0.75rem 0 2.5rem;
      }

      .cards {
        padding-left: 0.75rem;
        gap: 0.75rem;
      }

      .card-content {
        padding: 1rem 0.85rem 1.4rem;
      }

      .card h3 {
        font-size: 1.2rem;
      }

      .card p {
        font-size: 0.9rem;
      }

      .card-price {
        font-size: 1.4rem;
        margin-bottom: 1.2rem;
      }

      .calendar-container {
        padding: 1.25rem;
        max-width: 350px;
      }

      .quick-date-buttons {
        gap: 0.4rem;
      }

      .quick-date-btn {
        padding: 0.4rem 0.3rem;
        min-height: 55px;
      }

      .date-label {
        font-size: 0.85rem;
      }

      .date-value {
        font-size: 0.75rem;
      }

      .calendar-open-btn {
        padding: 0.4rem 0.6rem;
        font-size: 0.75rem;
        min-height: 55px;
      }

      .time-slots-grid {
        grid-template-columns: 1fr;
        gap: 0.75rem;
      }

      .time-slot {
        padding: 1rem;
        font-size: 1.1rem;
      }

      .weekly-dates-grid {
        grid-template-columns: repeat(7, 1fr);
        gap: 0.3rem;
      }

      .weekly-day-card {
        padding: 0.5rem;
        min-height: 85px;
      }

      .weekly-day-header {
        font-size: 0.75rem;
        margin-bottom: 0.3rem;
      }

      .weekly-day-date {
        font-size: 1rem;
        margin-bottom: 0.3rem;
      }

      .weekly-time-slot {
        padding: 0.2rem 0.4rem;
        font-size: 0.7rem;
      }

      .modal-content {
        padding: 1.5rem;
        margin: 1rem;
      }

      .payment-row {
        flex-direction: column;
        align-items: flex-start;
        gap: 0.5rem;
        margin-bottom: 1.5rem;
      }

      .copy-group {
        width: 100%;
        justify-content: space-between;
      }

      .copy-text {
        font-size: 0.9rem;
      }
    }

    @media (min-width: 481px) and (max-width: 767px) {
      .card {
        flex: 0 0 65vw;
        max-width: 250px;
      }
    }

    @media (min-width: 768px) {
      .card {
        flex: 0 0 208px;
        max-width: 208px;
      }
    }

    @media (min-width: 1200px) {
      .card {
        flex: 0 0 224px;
        max-width: 224px;
      }
    }

    /* Improve touch targets */
    @media (hover: none) and (pointer: coarse) {
      button, .card, .date-cell, .time-slot, .weekly-day-card, .quick-date-btn {
        min-height: 44px;
      }

      .card button {
        min-height: 48px;
        padding: 0.75rem 0;
      }

      .time-slot {
        min-height: 54px;
      }

      .weekly-time-slot {
        min-height: 32px;
      }
    }

    /* Reduce animations on low-end devices */
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }
  </style>
</head>

