  <script>
    function openModal(title, price) {
      document.getElementById('modal-title').textContent = title;
      document.getElementById('modal-price').textContent = price;
      document.getElementById('modal').style.display = 'flex';
      document.querySelector('.modal-content .close').focus(); // Fókusz a bezárás gombra
      document.body.style.overflow = 'hidden';
    }

    function openModalWithReference(title, price) {
      document.getElementById('modal-title').textContent = title;
      document.getElementById('modal-price').textContent = price;
      document.getElementById('payment-reference').textContent = title;
      document.getElementById('modal').style.display = 'flex';
      document.querySelector('.modal-content .close').focus(); // Fókusz a bezárás gombra
      document.body.style.overflow = 'hidden';

      // Automatikusan másoljuk a fizetési adatokat
      setTimeout(() => {
        initiatePayment(title, price);
      }, 500);
    }

    function initiatePayment(title, price) {
      const paymentData = {
        recipient: 'Zoltán Dalma',
        accountNumber: '11773384-03770582',
        amount: price,
        reference: title,
        message: `Vásárlás: ${title}`
      };

      // Próbáljuk meg megnyitni a banki alkalmazást (ahol támogatott)
      tryOpenBankingApp(paymentData);

      // Másoljuk az összes adatot a vágólapra
      copyPaymentDataToClipboard(paymentData);

      // Értesítjük a felhasználót
      showPaymentToast();
    }

    function tryOpenBankingApp(paymentData) {
      // Közvetlenül nem tudjuk megnyitni a banki appokat biztonsági okokból,
      // de próbálkozhatunk általános URL scheme-ekkel

      // OTP Bank (ha támogatja)
      const otpUrl = `otpbank://transfer?recipient=${encodeURIComponent(paymentData.recipient)}&account=${encodeURIComponent(paymentData.accountNumber)}&amount=${paymentData.amount}&message=${encodeURIComponent(paymentData.message)}`;

      // K&H Bank (ha támogatja)
      const khUrl = `khbank://transfer?recipient=${encodeURIComponent(paymentData.recipient)}&account=${encodeURIComponent(paymentData.accountNumber)}&amount=${paymentData.amount}&message=${encodeURIComponent(paymentData.message)}`;

      // Általános banking URL
      const genericBankingUrl = `banking://transfer?recipient=${encodeURIComponent(paymentData.recipient)}&account=${encodeURIComponent(paymentData.accountNumber)}&amount=${paymentData.amount}&message=${encodeURIComponent(paymentData.message)}`;

      // Próbáljuk meg megnyitni - csak akkor fog működni, ha az app telepítve van
      const urls = [otpUrl, khUrl, genericBankingUrl];

      urls.forEach((url, index) => {
        setTimeout(() => {
          try {
            window.location.href = url;
          } catch (e) {
            console.log(`Banking URL ${index + 1} failed:`, e);
          }
        }, index * 1000);
      });
    }

    function copyPaymentDataToClipboard(paymentData) {
      const paymentText = `Kedvezményezett: ${paymentData.recipient}
Számlaszám: ${paymentData.accountNumber}
Összeg: ${paymentData.amount} Ft
Közlemény: ${paymentData.message}`;

      try {
        const textarea = document.createElement('textarea');
        textarea.value = paymentText;
        textarea.style.position = 'fixed';
        textarea.style.opacity = '0';
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand('copy');
        document.body.removeChild(textarea);
      } catch (err) {
        console.log('Clipboard copy failed:', err);
      }
    }

    function showPaymentToast() {
      const toast = document.createElement('div');
      toast.className = 'toast payment-toast';
      toast.innerHTML = `
        <div style="text-align: center;">
          <div style="font-size: 1.1em; margin-bottom: 0.5rem;">💳 Fizetési adatok előkészítve</div>
          <div style="font-size: 0.9em; opacity: 0.9;">Banki app megnyitása...</div>
          <div style="font-size: 0.8em; opacity: 0.8; margin-top: 0.3rem;">Adatok vágólapra másolva</div>
        </div>
      `;
      document.body.appendChild(toast);

      setTimeout(() => toast.classList.add('show'), 10);
      setTimeout(() => {
        toast.classList.remove('show');
        setTimeout(() => toast.remove(), 300);
      }, 4000);
    }

    function closeModal() {
      document.getElementById('modal').style.display = 'none';
      document.body.style.overflow = '';
    }

    function copyText(text) {
      try {
        const textarea = document.createElement('textarea');
        textarea.value = text;
        textarea.style.position = 'fixed';
        textarea.style.opacity = '0';
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand('copy');
        document.body.removeChild(textarea);
        const toast = document.createElement('div');
        toast.className = 'toas
